// The contexts the design system's components read. Surfaces nest them per
// story and per comment, like the reference's provider stacks.
import { createContext } from "react";

export const ThemeContext = createContext({ name: "light", className: null });
export const LoggingSurfaceContext = createContext({ surface: "root", path: "root", depth: 0 });
export const HoverStateContext = createContext(null);
export const FocusScopeContext = createContext(null);
export const LayerContext = createContext({ container: null, depth: 0 });
export const ImpressionContext = createContext(null);
export const VisualCompletionContext = createContext({ ignore: false });
export const TypeScaleContext = createContext("default");
