// The page's configuration, from the inline JSON the build writes into
// index.html: the frozen clock, the viewer, feature flags.
const element = document.getElementById("site-config");
const config = element ? JSON.parse(element.textContent) : {};

export const NOW = config.now ?? 0;
export const VIEWER_ID = config.viewerId ?? null;
export const SITE_NAME = config.siteName ?? "Circlet";
export const flags = config.flags ?? {};
export const benchmarkMode = window.top !== window || new URLSearchParams(location.search).has("benchmark");

export default config;
