// Batches logging events per channel and flushes them, serialized, to a sink
// after the current task. The sink drops them; the batching, serialization
// and bookkeeping are the measured part.
import { afterTask, registerBusyCheck } from "Workload";
import { nowSeconds } from "CurrentTime";

const queues = new Map();
let flushScheduled = false;
let sequence = 0;
const sinkSizes = [];
const sessionId = "s-0001";

function flush() {
  flushScheduled = false;
  for (const [channel, events] of queues) {
    if (!events.length) {
      continue;
    }
    const batch = {
      channel,
      session: sessionId,
      time: nowSeconds(),
      sent: performance.now(),
      events: events.map((event) => JSON.stringify(event)),
    };
    sinkSizes.push(JSON.stringify(batch).length);
    if (sinkSizes.length > 100) {
      sinkSizes.shift();
    }
    events.length = 0;
  }
}

registerBusyCheck(() => flushScheduled);

const EventLogger = {
  log(channel, payload) {
    let queue = queues.get(channel);
    if (!queue) {
      queue = [];
      queues.set(channel, queue);
    }
    queue.push({ seq: sequence++, ts: performance.now(), payload });
    if (!flushScheduled) {
      flushScheduled = true;
      afterTask(flush);
    }
  },
  sinkSizes,
};

export default EventLogger;
