// Loads package files on demand. The build writes the module → file map
// into the page; requesting a module that isn't defined yet loads its file
// with a script element and resolves once the module is defined. In the
// benchmark every file is loaded before the first step, so only the
// modules' factories run in the steps.
import { track } from "Workload";

const element = document.getElementById("resource-map");
const resourceMap = element ? JSON.parse(element.textContent) : { modules: {}, files: [] };
const loadedFiles = new Map();

export function loadFile(file) {
  let promise = loadedFiles.get(file);
  if (!promise) {
    promise = new Promise((resolve, reject) => {
      const script = document.createElement("script");
      script.src = file;
      script.async = true;
      script.onload = () => resolve();
      script.onerror = () => reject(new Error(`Failed to load ${file}`));
      document.head.appendChild(script);
    });
    loadedFiles.set(file, promise);
  }
  return promise;
}

// Loads the files that define `names` and, as each module is defined, the
// files of its dependencies, so that requiring the modules succeeds.
function loadClosure(names, seen) {
  const pending = [];
  for (const name of names) {
    if (seen.has(name)) {
      continue;
    }
    seen.add(name);
    const defined = __moduleRuntime.isDefined(name) ? Promise.resolve() : loadFile(fileOf(name)).then(() => new Promise((resolve) => __moduleRuntime.whenDefined(name, resolve)));
    pending.push(defined.then(() => loadClosure(__moduleRuntime.modules[name].dependencies, seen)));
  }
  return Promise.all(pending);
}

function fileOf(name) {
  const file = resourceMap.modules[name];
  if (!file) {
    throw new Error(`No file defines module ${name}`);
  }
  return file;
}

export function loadModules(names) {
  const promise = loadClosure(names, new Set()).then(() => names.map((name) => requireDynamic(name)));
  return track(promise);
}

export function preloadAll() {
  for (const script of document.querySelectorAll("script[src]")) {
    loadedFiles.set(script.getAttribute("src"), Promise.resolve());
  }
  return Promise.all(resourceMap.files.map(loadFile));
}
