// A reference to a module that may live in a package file that isn't
// loaded yet. The packager includes every JSResource("Name") target.
import { loadModules } from "Bootloader";

const resources = new Map();
const ready = new Set();

// Whether the module and everything it requires are defined, so that
// requiring it can't fail on a file that hasn't arrived yet.
function isClosureDefined(name, visiting = new Set()) {
  if (ready.has(name) || visiting.has(name)) {
    return true;
  }
  if (!__moduleRuntime.isDefined(name)) {
    return false;
  }
  visiting.add(name);
  const complete = __moduleRuntime.modules[name].dependencies.every((dependency) => isClosureDefined(dependency, visiting));
  if (complete && visiting.size === 1) {
    ready.add(name);
  }
  return complete;
}

class Resource {
  constructor(name) {
    this.name = name;
    this.module = null;
    this.promise = null;
  }

  getModuleId() {
    return this.name;
  }

  getModuleIfRequired() {
    if (this.module === null && isClosureDefined(this.name)) {
      this.module = requireDynamic(this.name);
    }
    return this.module;
  }

  load() {
    if (this.module !== null) {
      return Promise.resolve(this.module);
    }
    if (this.promise === null) {
      this.promise = loadModules([this.name]).then(([exports]) => (this.module = exports));
    }
    return this.promise;
  }
}

export default function JSResource(name) {
  let resource = resources.get(name);
  if (!resource) {
    resource = new Resource(name);
    resources.set(name, resource);
  }
  return resource;
}
