// The prepared GraphQL responses, as the text a server would stream: one
// JSON payload per line. The page fetches them all before the first step.
import { track } from "Workload";

const responses = new Map();

export function preloadResponses(baseUrl) {
  return track(
    fetch(new URL("data/responses.json", baseUrl))
      .then((response) => response.json())
      .then((manifest) =>
        Promise.all(
          Object.entries(manifest).map(([key, file]) =>
            fetch(new URL(`data/${file}`, baseUrl))
              .then((response) => response.text())
              .then((text) => responses.set(key, text)),
          ),
        ),
      ),
  );
}

export function getResponseText(key) {
  return responses.get(key) ?? null;
}
