// Initializes the fbt runtime: the translation table (the page is in the
// source locale, so it's empty and fbt falls back to the source strings, as
// it does for untranslated strings) and the viewer's locale and gender.
// Results are plain strings, or arrays when a parameter is an element:
// fbt 1.0's result objects carry the element marker of React before 19.
import { init, IntlVariations } from "fbt";

let initialized = false;

export function setupFbt() {
  if (initialized) {
    return;
  }
  initialized = true;
  init({
    translations: { en_US: {} },
    hooks: {
      getFbtResult: ({ contents }) => (contents.length === 1 ? contents[0] : contents.every((part) => typeof part === "string") ? contents.join("") : contents),
      getViewerContext: () => ({ GENDER: IntlVariations.GENDER_UNKNOWN, locale: "en_US" }),
    },
  });
}
