// Names the part of the page its children belong to, for click and
// impression logging, and marks the DOM with it for Hyperion's surface
// bookkeeping.
import { useContext, useMemo } from "react";
import { LoggingSurfaceContext } from "UIContexts";

export default function LoggingSurface({ name, children, as: Tag = null, xstyle }) {
  const parent = useContext(LoggingSurfaceContext);
  const value = useMemo(() => ({ surface: name, path: `${parent.path}/${name}`, depth: parent.depth + 1 }), [name, parent]);
  const content = <LoggingSurfaceContext.Provider value={value}>{children}</LoggingSurfaceContext.Provider>;
  if (Tag === null) {
    return content;
  }
  return (
    <Tag data-surface={value.path} className={xstyle?.className}>
      {content}
    </Tag>
  );
}
