// The page's one Relay environment.
import { Environment, RecordSource, Store } from "relay-runtime";
import RelayNetworkLayer from "RelayNetworkLayer";
import RelayOperationLoader from "RelayOperationLoader";
import EventLogger from "EventLogger";

const LOGGED_EVENTS = new Set(["execute.start", "execute.complete", "execute.next.end", "store.publish", "store.notify.complete", "queryresource.fetch"]);

function relayLog(event) {
  if (LOGGED_EVENTS.has(event.name)) {
    EventLogger.log("relay_log", { name: event.name, id: event.executeId ?? null });
  }
}

const store = new Store(new RecordSource(), { gcReleaseBufferSize: 10, operationLoader: RelayOperationLoader });

const RelayEnvironment = new Environment({
  network: RelayNetworkLayer,
  store,
  operationLoader: RelayOperationLoader,
  log: relayLog,
});

export default RelayEnvironment;
