// Handles the page's inline JSON payloads: each is a list of
// [moduleName, method, args] calls, run once the module is available.
// Preloaded GraphQL responses arrive this way, as calls to
// RelayPrefetchedStreamCache.
import { applyWithGuard } from "ErrorGuard";

function handle(payload) {
  for (const [moduleName, method, args] of payload.require ?? []) {
    requireLazy([moduleName], (module) => {
      const target = module.default ?? module;
      applyWithGuard(target[method], target, args, { name: `ServerJS:${moduleName}.${method}` });
    });
  }
}

export function processInlinePayloads() {
  let count = 0;
  for (const script of document.querySelectorAll('script[type="application/json"][data-sjs]')) {
    if (script.hasAttribute("data-processed")) {
      continue;
    }
    script.setAttribute("data-processed", "1");
    handle(JSON.parse(script.textContent));
    count++;
  }
  return count;
}
