// The routes the client knows without asking the server. Other URLs (a
// profile's vanity name) are resolved with a route query, as the reference
// resolves its URLs.
import JSResource from "JSResource";

export const HOME_ENTRY_POINT = "HomePage.entrypoint";
export const PROFILE_ENTRY_POINT = "ProfilePage.entrypoint";

export function matchStaticRoute(url) {
  const path = url.split("?")[0];
  if (path === "/" || path === "") {
    return { entryPoint: HOME_ENTRY_POINT, params: {} };
  }
  const post = path.match(/^\/posts\/([^/]+)$/);
  if (post) {
    return { entryPoint: HOME_ENTRY_POINT, params: {}, dialog: { kind: "post", storyId: post[1] } };
  }
  return null;
}

export function entryPointResource(name) {
  return JSResource(name);
}

// App paths ("/", "/posts/<id>") live under the page's <base href>, so that
// the page works from any directory: history entries point into the base
// directory, and the app path is kept in the history state.
export function appPathToLocation(appPath) {
  return new URL(`.${appPath}`, document.baseURI).href;
}

export function currentAppPath() {
  return history.state?.url ?? "/";
}
