// Resolves the normalization artifacts of @module fragments, which the
// server names in its responses, to their modules. They're in package files
// that may not be loaded; get() answers only for defined modules, and load()
// loads the file.
import JSResource from "JSResource";

function unwrap(exports) {
  return exports != null && exports.default !== undefined ? exports.default : exports;
}

const RelayOperationLoader = {
  get(reference) {
    const module = JSResource(reference).getModuleIfRequired();
    return module === null ? null : unwrap(module);
  },
  load(reference) {
    return JSResource(reference).load().then(unwrap);
  },
};

export default RelayOperationLoader;
