// Idle tracking and step events for the benchmark. A step ends when no
// tracked promise (a replayed response, a lazy module, a logging flush) is
// pending, no React root has scheduled work, and the post-commit trackers
// have flushed.

const pending = new Set();
const roots = new Set();
const idleChecks = [];
let version = 0;

const taskQueue = [];
let channel = null;

// Runs `callback` in a task of its own, without the clamping of nested
// timers.
export function afterTask(callback) {
  if (channel === null) {
    channel = new MessageChannel();
    channel.port1.onmessage = () => {
      const next = taskQueue.shift();
      if (next) {
        next();
      }
    };
  }
  taskQueue.push(callback);
  channel.port2.postMessage(null);
}

export function nextTask() {
  return new Promise((resolve) => afterTask(resolve));
}

export function track(promise) {
  pending.add(promise);
  version++;
  const done = () => pending.delete(promise);
  promise.then(done, done);
  return promise;
}

// Lets whenIdle() see a React root's pending work (private fields of React
// DOM's root).
export function trackReactRoot(root) {
  roots.add(root._internalRoot);
}

// `check` returns true while the module that registered it has work queued.
export function registerBusyCheck(check) {
  idleChecks.push(check);
}

function busy() {
  for (const root of roots) {
    if (root.pendingLanes !== 0 || root.callbackNode !== null) {
      return true;
    }
  }
  return idleChecks.some((check) => check());
}

export async function whenIdle() {
  for (;;) {
    const start = version;
    while (pending.size) {
      await Promise.allSettled([...pending]);
    }
    await nextTask();
    await new Promise((resolve) => setTimeout(resolve, 0));
    await nextTask();
    if (!pending.size && !busy() && version === start) {
      return;
    }
  }
}

export function emitStepEvent(name, detail) {
  window.dispatchEvent(new CustomEvent(`social-${name}`, { detail }));
}

export function nextEvent(name) {
  return new Promise((resolve) => window.addEventListener(`social-${name}`, (event) => resolve(event.detail), { once: true }));
}
