// The home page's entry point: its root component and the queries the page
// needs, which the server preloads into the HTML on a first visit.
import JSResource from "JSResource";
import HomePageFeedQuery$parameters from "HomePageFeedQuery$parameters";
import HomePageStoriesTrayQuery$parameters from "HomePageStoriesTrayQuery$parameters";
import HomePageLeftRailQuery$parameters from "HomePageLeftRailQuery$parameters";
import HomePageRightRailQuery$parameters from "HomePageRightRailQuery$parameters";
import HomePageInlineComposerQuery$parameters from "HomePageInlineComposerQuery$parameters";
import { HOME_FEED_INITIAL_COUNT } from "HomeFeedConfig";

const HomePageEntryPoint = {
  root: JSResource("HomePage.react"),
  getPreloadProps() {
    return {
      queries: {
        feed: { parameters: HomePageFeedQuery$parameters, variables: { count: HOME_FEED_INITIAL_COUNT } },
        tray: { parameters: HomePageStoriesTrayQuery$parameters, variables: {} },
        leftRail: { parameters: HomePageLeftRailQuery$parameters, variables: {} },
        rightRail: { parameters: HomePageRightRailQuery$parameters, variables: {} },
        composer: { parameters: HomePageInlineComposerQuery$parameters, variables: {} },
      },
    };
  },
};

export default HomePageEntryPoint;
