// The frozen clock: every timestamp the app shows is relative to the
// journey's "now". performance.now() stays real and is only used for timing
// logs, never for control flow.
import { NOW } from "SiteConfig";

export function nowSeconds() {
  return NOW;
}

const relativeFormat = new Intl.RelativeTimeFormat("en-US", { numeric: "auto", style: "short" });
const dateFormat = new Intl.DateTimeFormat("en-US", { month: "long", day: "numeric", timeZone: "UTC" });
const yearDateFormat = new Intl.DateTimeFormat("en-US", { month: "long", day: "numeric", year: "numeric", timeZone: "UTC" });

// The compact form under a story's author ("3h", "2d").
export function shortRelativeTime(seconds) {
  const delta = Math.max(0, NOW - seconds);
  if (delta < 60) {
    return "Just now";
  }
  if (delta < 3600) {
    return `${Math.floor(delta / 60)}m`;
  }
  if (delta < 86400) {
    return `${Math.floor(delta / 3600)}h`;
  }
  if (delta < 7 * 86400) {
    return `${Math.floor(delta / 86400)}d`;
  }
  const date = new Date(seconds * 1000);
  return delta < 300 * 86400 ? dateFormat.format(date) : yearDateFormat.format(date);
}

export function longRelativeTime(seconds) {
  const delta = NOW - seconds;
  if (delta < 3600) {
    return relativeFormat.format(-Math.max(1, Math.floor(delta / 60)), "minute");
  }
  if (delta < 86400) {
    return relativeFormat.format(-Math.floor(delta / 3600), "hour");
  }
  if (delta < 30 * 86400) {
    return relativeFormat.format(-Math.floor(delta / 86400), "day");
  }
  return yearDateFormat.format(new Date(seconds * 1000));
}

export function fullDate(seconds) {
  return new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit", timeZone: "UTC" }).format(new Date(seconds * 1000));
}
