// The network layer. A request looks up its prepared response by persisted
// query id and variables and delivers it one line per task, the way chunks
// of a streamed response arrive, so that @stream and @defer payloads, React's
// scheduler tasks and the loading states interleave as on the reference
// site. Each line is parsed when it's delivered.
import { Network, Observable } from "relay-runtime";
import responseKey from "RelayResponseKey";
import { getResponseText } from "RelayResponseStore";
import RelayPrefetchedStreamCache from "RelayPrefetchedStreamCache";
import { afterTask, track } from "Workload";
import PerfLogger from "PerfLogger";
import EventLogger from "EventLogger";

let requestCount = 0;

function fetchQuery(params, variables) {
  const key = responseKey(params.id, variables);
  return Observable.create((sink) => {
    const instance = ++requestCount;
    const prefetched = RelayPrefetchedStreamCache.take(key);
    let lines = null;
    if (prefetched === null) {
      const text = getResponseText(key);
      if (text === null) {
        sink.error(new Error(`No prepared response for ${params.name} ${key}`));
        return undefined;
      }
      lines = text.split("\n").filter(Boolean);
    }
    const count = prefetched !== null ? prefetched.length : lines.length;
    PerfLogger.markerStart("relay_request", instance);
    PerfLogger.markerAnnotate("relay_request", { operation: params.name, prefetched: prefetched !== null ? 1 : 0, chunks: count }, instance);
    let cancelled = false;
    let resolveTracked;
    track(new Promise((resolve) => (resolveTracked = resolve)));
    const deliver = (index) => {
      afterTask(() => {
        if (cancelled) {
          return;
        }
        const payload = prefetched !== null ? prefetched[index] : JSON.parse(lines[index]);
        PerfLogger.markerPoint("relay_request", `chunk_${index}`, instance);
        sink.next(payload);
        if (index + 1 < count) {
          deliver(index + 1);
        } else {
          sink.complete();
          PerfLogger.markerEnd("relay_request", "success", instance);
          EventLogger.log("relay", { operation: params.name, id: params.id, chunks: count });
          resolveTracked();
        }
      });
    };
    deliver(0);
    return () => {
      cancelled = true;
      resolveTracked();
    };
  });
}

export default Network.create(fetchQuery);
