// Responses the server streamed into the page's HTML for queries it
// expected the page to run. The inline payloads call next() for each chunk;
// the network layer takes them instead of making a request.
const streams = new Map();

const RelayPrefetchedStreamCache = {
  next(key, payloads) {
    let stream = streams.get(key);
    if (!stream) {
      stream = [];
      streams.set(key, stream);
    }
    for (const payload of payloads) {
      stream.push(payload);
    }
  },
  take(key) {
    const stream = streams.get(key) ?? null;
    streams.delete(key);
    return stream;
  },
  has(key) {
    return streams.has(key);
  },
};

export default RelayPrefetchedStreamCache;
