// Timing markers, in the shape of the reference's performance logger: each
// interaction opens a marker, annotates it, adds points with
// performance.now() stamps and closes it; closed markers are serialized into
// the event batch. Timestamps never influence control flow.
import EventLogger from "EventLogger";

let nextInstance = 1;
const open = new Map();

class Marker {
  constructor(name, instanceKey) {
    this.name = name;
    this.instanceKey = instanceKey;
    this.start = performance.now();
    this.points = [];
    this.annotations = {};
    this.intAnnotations = {};
  }
}

function key(name, instanceKey) {
  return `${name}:${instanceKey}`;
}

const PerfLogger = {
  markerStart(name, instanceKey = 0) {
    const marker = new Marker(name, instanceKey);
    open.set(key(name, instanceKey), marker);
    return marker;
  },
  markerPoint(name, point, instanceKey = 0, data = null) {
    const marker = open.get(key(name, instanceKey));
    if (marker) {
      marker.points.push({ name: point, timestamp: performance.now(), data });
    }
  },
  markerAnnotate(name, annotations, instanceKey = 0) {
    const marker = open.get(key(name, instanceKey));
    if (!marker) {
      return;
    }
    for (const field of Object.keys(annotations)) {
      const value = annotations[field];
      if (typeof value === "number") {
        marker.intAnnotations[field] = value;
      } else {
        marker.annotations[field] = String(value);
      }
    }
  },
  markerEnd(name, action, instanceKey = 0) {
    const id = key(name, instanceKey);
    const marker = open.get(id);
    if (!marker) {
      return;
    }
    open.delete(id);
    const end = performance.now();
    EventLogger.log("perf", {
      marker: marker.name,
      instance: marker.instanceKey,
      action,
      duration: end - marker.start,
      points: marker.points.map((p) => ({ name: p.name, offset: p.timestamp - marker.start, data: p.data })),
      annotations: marker.annotations,
      intAnnotations: marker.intAnnotations,
    });
  },
  newInstanceKey() {
    return nextInstance++;
  },
};

export default PerfLogger;
