// The key a prepared response is stored under: the persisted query's id and
// its variables, with the keys sorted. scripts/lib/response-key.mjs computes
// the same key at build time.
function stable(value) {
  if (Array.isArray(value)) {
    return `[${value.map(stable).join(",")}]`;
  }
  if (value !== null && typeof value === "object") {
    return `{${Object.keys(value).filter((key) => value[key] !== undefined).sort().map((key) => `${JSON.stringify(key)}:${stable(value[key])}`).join(",")}}`;
  }
  return JSON.stringify(value);
}

export default function responseKey(docId, variables) {
  return `${docId}:${stable(variables)}`;
}
