// Tracks when the page is visually complete after each interaction: a
// MutationObserver over the root collects mutated subtrees, and after the
// commit, a walk over the landmark around each one checks every element's
// style, hidden and data-visualcompletion attributes and registers images
// with an IntersectionObserver. The reference runs a walk like this after
// every mutation burst.
import { afterTask, registerBusyCheck } from "Workload";
import PerfLogger from "PerfLogger";

const LANDMARKS = '[role="main"],[role="dialog"],[role="banner"],[role="navigation"],[role="complementary"],[data-vc-root]';
const pendingRoots = new Set();
let scheduled = false;
let observer = null;
let imageObserver = null;
const imageState = new WeakMap();
let walkCount = 0;

function landmarkOf(node) {
  const element = node.nodeType === 1 ? node : node.parentElement;
  return element?.closest(LANDMARKS) ?? element;
}

function walk(root, result) {
  const stack = [root];
  while (stack.length) {
    const element = stack.pop();
    result.visited++;
    const style = element.getAttribute("style");
    if (element.hasAttribute("hidden") || (style !== null && style.indexOf("display: none") !== -1)) {
      result.hidden++;
      continue;
    }
    const vc = element.getAttribute("data-visualcompletion");
    if (vc === "ignore" || vc === "ignore-dynamic") {
      result.ignored++;
      continue;
    }
    if (vc === "media-vc-image" || element.tagName === "IMG" || element.tagName === "image") {
      result.images++;
      if (!imageState.has(element)) {
        imageState.set(element, walkCount);
        imageObserver.observe(element);
      }
    }
    if (vc === "loading-state") {
      result.loading++;
    }
    for (let child = element.lastElementChild; child !== null; child = child.previousElementSibling) {
      stack.push(child);
    }
  }
}

function flush() {
  scheduled = false;
  const roots = [...pendingRoots];
  pendingRoots.clear();
  const result = { visited: 0, hidden: 0, ignored: 0, images: 0, loading: 0 };
  const landmarks = new Set();
  for (const node of roots) {
    if (node.isConnected) {
      const landmark = landmarkOf(node);
      if (landmark) {
        landmarks.add(landmark);
      }
    }
  }
  for (const landmark of landmarks) {
    walk(landmark, result);
  }
  walkCount++;
  const instance = PerfLogger.newInstanceKey();
  PerfLogger.markerStart("visual_completion", instance);
  PerfLogger.markerAnnotate("visual_completion", result, instance);
  PerfLogger.markerEnd("visual_completion", result.loading ? "loading" : "complete", instance);
}

registerBusyCheck(() => scheduled);

export function startVisualCompletion(root) {
  imageObserver = new IntersectionObserver((entries) => {
    for (const entry of entries) {
      if (entry.isIntersecting) {
        imageObserver.unobserve(entry.target);
      }
    }
  });
  observer = new MutationObserver((records) => {
    for (const record of records) {
      pendingRoots.add(record.target);
    }
    if (!scheduled) {
      scheduled = true;
      afterTask(flush);
    }
  });
  observer.observe(root, { childList: true, subtree: true, attributes: true, attributeFilter: ["hidden", "style", "data-visualcompletion"] });
}
